import { writeFileSync } from "node:fs";
import { catalog } from "../src/registry.js";
let output =
  "# Content status\n\nGenerated by `npm run catalog` from `src/registry.js`. See CONTENT_CHECKLIST.md for delivery stages.\n";
for (const [section, entries] of Object.entries(catalog)) {
  output += `\n## ${section} (${entries.length})\n\n| Entry | Status | Notes |\n| --- | --- | --- |\n`;
  for (const entry of entries)
    output += `| ${entry.name ?? entry.key} | ${entry.status} | ${
      entry.notes ??
      (section === "recipes" && entry.ingredients
        ? `${Object.entries(entry.ingredients)
            .map(([key, n]) => `${n} ${key}`)
            .join(" + ")} → ${entry.count} ${entry.output}; ${entry.station}`
        : "")
    } |\n`;
}
writeFileSync(new URL("../CONTENT_STATUS.md", import.meta.url), output);
